{
  "name": "ACME Bank Statement Pipeline",
  "clientId": "acme-corp",
  "description": "Daily CAMT.053 bank statement ingestion and Kafka forwarding",
  "windowConfig": {
    "openTrigger": {
      "type": "TIME_BASED",
      "openCron": "0 6 * * *",
      "timeZone": "UTC"
    },
    "closeTrigger": {
      "type": "FILE_ARRIVAL",
      "integrationId": "{{sftpIntegrationId}}",
      "filePattern": "camt053_*.xml",
      "pollInterval": "PT1M"
    },
    "maxOpenDuration": "PT18H",
    "allowEmptyClose": false,
    "lateEventBehaviour": "REJECT"
  },
  "actions": [
    {
      "name": "Parse CAMT.053 and forward to Kafka",
      "condition": "ON_FILE_ARRIVED",
      "executionOrder": 10,
      "continueOnFailure": false,
      "steps": [
        {
          "name": "Parse CAMT.053 XML",
          "stepType": "PARSE_FILE",
          "executionOrder": 1,
          "enabled": true,
          "config": {
            "fileSpecId": "{{specId}}",
            "recordType": "CAMT053_ENTRY",
            "failOnParseError": false
          },
          "retryPolicy": {
            "maxAttempts": 3,
            "initialDelay": "PT1S",
            "backoffMultiplier": 2.0,
            "maxDelay": "PT30S"
          }
        },
        {
          "name": "Validate entries",
          "stepType": "VALIDATE",
          "executionOrder": 2,
          "enabled": true,
          "config": {
            "fileSpecId": "{{specId}}",
            "rejectOnError": false,
            "reportWarnings": true
          },
          "retryPolicy": {
            "maxAttempts": 1
          }
        },
        {
          "name": "Publish to Kafka",
          "stepType": "NOTIFY",
          "executionOrder": 3,
          "enabled": true,
          "config": {
            "topic": "bank.statement.entries",
            "keyField": "entryRef",
            "includeFields": [
              "statementId", "iban", "currency",
              "entryRef", "amount", "creditDebitIndicator",
              "bookingDate", "valueDate", "bankTxCode",
              "endToEndId", "remittanceInfo"
            ]
          },
          "retryPolicy": {
            "maxAttempts": 5,
            "initialDelay": "PT2S",
            "backoffMultiplier": 2.0,
            "maxDelay": "PT60S",
            "retryableErrors": ["TimeoutException", "IOException"]
          }
        }
      ]
    },
    {
      "name": "Alert on pipeline failure",
      "condition": "ON_ERROR",
      "executionOrder": 10,
      "steps": [
        {
          "name": "Send failure alert",
          "stepType": "NOTIFY",
          "executionOrder": 1,
          "enabled": true,
          "config": {
            "channel": "WEBHOOK",
            "url": "https://hooks.slack.com/services/YOUR/WEBHOOK/URL",
            "template": "CAMT.053 pipeline failed for window {{windowId}}: {{errorMessage}}"
          },
          "retryPolicy": {
            "maxAttempts": 3
          }
        }
      ]
    }
  ],
  "tags": {
    "client": "acme-corp",
    "standard": "ISO20022",
    "fileType": "camt053",
    "environment": "production"
  },
  "createdBy": "admin",
  "updatedBy": "admin"
}
